{"code": "async (page) => {
    // Get the main content element
    const main = await page.locator('main').first();
    if (!main) return null;
    const text = await main.innerText();
    // Find the start of "Version 0.19" and end before "Version 0.19.1"
    const lines = text.split('\n');
    let startIdx = -1;
    let endIdx = -1;
    for (let i = 0; i < lines.length; i++) {
        if (lines[i].includes('Version 0.19') && !lines[i].includes('Version 0.19.1') && !lines[i].includes('Version 0.19.2')) {
            startIdx = i;
            break;
        }
    }
    if (startIdx === -1) return text; // fallback
    for (let i = startIdx + 1; i < lines.length; i++) {
        if (lines[i].includes('Version 0.19.1') || lines[i].includes('Version 0.19.2')) {
            endIdx = i;
            break;
        }
    }
    const relevant = endIdx === -1 ? lines.slice(startIdx) : lines.slice(startIdx, endIdx);
    return relevant.join('\n');
}"}

